    "@mdi/font": "^7.4.47",
    "bootstrap": "^5.3.3",
    "chart.js": "^4.4.1",
    "codemirror": "^5.47.0",
    "flag-icon-css": "4.1.7",
    "font-awesome": "4.7.0",
    "jquery": "3.7.1",    
    "del": "^6.1.1",
    "gulp-sourcemaps": "^3.0.0",
    "jquery-file-upload": "4.0.11",
