.page-body-wrapper {
  min-height: calc(100vh - #{$navbar-height});
  @include display-flex();
  @include flex-direction(row);
  padding-left: 0;
  padding-right: 0;
  padding-top: 1.875rem;
  background: $content-bg;

  &.full-page-wrapper {
    width: 100%;
    min-height: 100vh;
    padding-top: 0;
  }
}
.navbar {
  + .page-body-wrapper {
    padding-top: calc(#{$navbar-height} + 1.875rem);    
  }
}  

.main-panel {
  transition: width $action-transition-duration $action-transition-timing-function, margin $action-transition-duration $action-transition-timing-function;
  width: calc(100% - #{$sidebar-width-lg});
  min-height: calc(100vh - #{$navbar-height});
  @include display-flex();
  @include flex-direction(column);
  @media (max-width: 991px) {
    margin-left: 0;
    width: 100%;
  }
}

.content-wrapper {
  padding: 0 1.812rem 1.812rem;
  width: 100%;
  @include flex-grow(1);
  @media(max-width: 767px) {
    padding: 1.5rem 1.5rem;
  }
}
/* Navbar */

.navbar {
  font-weight: 400;
  transition:background $action-transition-duration $action-transition-timing-function;
  -webkit-transition:background $action-transition-duration $action-transition-timing-function;
  -moz-transition:background $action-transition-duration $action-transition-timing-function;
  -ms-transition:background $action-transition-duration $action-transition-timing-function;
  border-bottom: 4px solid $primary;  

  .navbar-brand-wrapper {
    background: $primary;
    transition: width $action-transition-duration $action-transition-timing-function, background $action-transition-duration $action-transition-timing-function;
    -webkit-transition: width $action-transition-duration $action-transition-timing-function, background $action-transition-duration $action-transition-timing-function;
    -moz-transition: width $action-transition-duration $action-transition-timing-function, background $action-transition-duration $action-transition-timing-function;
    -ms-transition: width $action-transition-duration $action-transition-timing-function, background $action-transition-duration $action-transition-timing-function;
    width: calc(#{$sidebar-width-lg} + #{$sidebar-margin-left});
    height: $navbar-height;
    .navbar-brand-inner-wrapper {
      margin-right: 1.3rem;
      margin-left: 1.8rem;
      .navbar-brand {
        color: lighten($gray-dark, 20%);
        font-size: 1.5rem;
        margin-right: 0;
        padding: .25rem 0;
        
        &.brand-logo-mini {
          display: none;
          @media(max-width: 991px) {
            display: inline-block;
            width: 3.125rem;
          }
        }

        &:active,
        &:focus,
        &:hover {
          color: lighten($gray-dark, 10%);
        }

        img {
          width: calc(#{$sidebar-width-lg} - 110px );
          max-width: 100%;
          height: 40px;
          margin: auto;
          vertical-align: middle;
        }
      }
      .navbar-toggler {
        padding: 0;
        color: $white;
        border: 0;
        &:focus {
          box-shadow: none;
          border: none;
        }
        @media(max-width: 991px) {
          display: none;
        }
      }
    }  
  }

  .navbar-menu-wrapper {
    background: $navbar-default-bg;
    transition: width $action-transition-duration $action-transition-timing-function;
    -webkit-transition: width $action-transition-duration $action-transition-timing-function;
    -moz-transition: width $action-transition-duration $action-transition-timing-function;
    -ms-transition: width $action-transition-duration $action-transition-timing-function;
    color: $navbar-menu-color;
    padding-left: 1.812rem;
    padding-right: 1.812rem;
    width: calc(100% - #{$sidebar-width-lg} - #{$sidebar-margin-left});
    height: $navbar-height;
    @media (max-width: 991px) {
      width: calc(100% - 55px);
      padding-left: 15px;
      padding-right: 15px;
    }

    .navbar-toggler {
      border: 0;
      color: inherit;
      font-size: 1.5rem;
      padding: 0;
      
      &:not(.navbar-toggler-right) {
        @media (max-width: 991px) {
          display: none;
        }
      }
      &.navbar-toggler-right{
        @media (max-width:991px){
          box-shadow: none;
          padding-left: 15px;
          padding-right: 11px;
        }
      }
    }

    .navbar-nav {
      @extend .d-flex;
      @extend .flex-row;
      @extend .align-self-stretch;
      @extend .align-items-stretch;
      .nav-item {
        @extend .d-flex;
        @extend .align-items-center;
        margin-left: 0.531rem;
        margin-right: 0.531rem;
        &:last-child {
          margin-right: 0;
        }
        .nav-link {
          color: inherit;
          font-size: $navbar-font-size;
        }
        &.nav-settings {
          @extend .align-self-stretch;
          @extend .align-items-center;
          border-left: 1px solid rgba($white, .24);
          margin: 0;
          padding-left: 1.5rem;
          .nav-link {
            padding: 0;
            text-align: center;
          }
          i {
            font-size: 1.5rem;
            vertical-align: middle;
          }
        }
        &.nav-profile {
          @extend .d-none;
          @extend .d-md-flex;
          @extend .align-items-center;
          margin-right: 0.25rem;
          margin-left: 0;
          img {
            width: 2.5rem;
            height: 2.5rem;
            border-radius: 4px;
          }
          .nav-profile-name {
            margin-left: .5rem;
            font-weight: 500;
            font-size: 1rem;
            @media (max-width: 767px) {
              display: none;
            }
          }
        }
        &.nav-user-status {
          @extend .d-none;
          @extend .d-lg-flex;
          margin-left: 0;
          p {
            color: #212529;
            font-size: 12px;
          }
        }
        &.nav-date {
          @extend .d-none;
          @extend .d-md-flex;
          .nav-link {
            h6 {
              font-weight: normal;
              font-size: .875rem;
            }
            i {
              margin-left: 0.562rem;
              font-size: 1.125rem;
            }
          }
        }
        &.dropdown {
          .dropdown-menu {
            @extend .dropdownAnimation;        
            border: none;
            -webkit-box-shadow: 0px 3px 21px 0px rgba(0, 0, 0, 0.2);
            box-shadow: 0px 3px 21px 0px rgba(0, 0, 0, 0.2);
          }
          .navbar-dropdown {
            position: absolute;            
            font-size: 0.9rem;
            margin-top: 0;
            right: 0;
            left: auto;
            top: $navbar-height;
            .rtl & {
              right: auto;
              left: 0;
            }

            .dropdown-item {
              @extend .d-flex;
              @extend .align-items-center;
              margin-bottom: 0;
              padding: .65rem 1.5rem;
              cursor: pointer;

              i {
                font-size: 17px;
              }

              .badge {
                margin-left: 2.5rem;
              }
              .ellipsis {
                max-width: 200px;
                overflow: hidden;
                text-overflow: ellipsis;
              }
              .rtl & {
                i {
                  @extend .me-0;
                  margin-left: 10px;
                }
                .badge {
                  margin-left: 0;
                  margin-right: 2.5rem;
                }
              }
            }

            .dropdown-divider {
              margin: 0;
            }
          }
          i {
            margin-right: .5rem;
            vertical-align: middle;
          }
          @media (max-width: 991px) {
            position: static;
            .navbar-dropdown {
              left: 20px;
              right: 20px;
              top: $navbar-height;
              width: calc(100% - 40px);
            }
          }
          .count-indicator {
            position: relative;
            padding: 0;
            text-align: center;
            width: 2.5rem;
            i {
              font-size: 1.25rem;
              margin-right: 0;
              vertical-align: middle;
            }
            .count {
              position: absolute;
              left: 50%;
              top: 10px;
              width: 7px;
              height: 7px;
              border-radius: 100%;
              background: $danger;
            }
            &:after {
              display: none;
            }
          }
        }
      }
      &.navbar-nav-right {
        margin-left: auto;
        .nav-item {
          .nav-link {
            -webkit-box-shadow: 0 5px 10px 0 rgba(230, 230, 243, 0.88);
                    box-shadow: 0 5px 10px 0 rgba(230, 230, 243, 0.88);
            border: 1px solid #e4e4f4;
            padding-left: .875rem;
            padding-right: .875rem;
            border-radius: 0.25rem;
            height: 2.5rem;
          }
        }
        @media (min-width: 992px) {
          .rtl & {
            margin-left: 0;
            margin-right: auto;
          }
        }
      }
    }
  }

  /* Navbar color variations */
  @each $color, $value in $theme-colors {
    &.navbar-#{$color} {
      .navbar-menu-wrapper {
        background: $value;
      }
      &:not(.navbar-light) {
        .navbar-menu-wrapper {
          .navbar-toggler {
            color: $white;
          }
          .nav-item {
            .nav-link {
              color: $white;
            }
            &.nav-user-status {
              p {
                color: $white;
              }
            }
          }
          .navbar-nav-right {
            .nav-item {
              .nav-link {
                box-shadow: none;
              }
            }
          }
        }
      }
    }
    &.navbar-light {
      .navbar-menu-wrapper {
        background: $white;
        border-left: 1px solid $border-color;
        .navbar-toggler {
          color: $dark;
        }
        .nav-item {
          .nav-link {
            color: $dark;
          }
          &.nav-search {
            .input-group {
              background: rgba($dark, .24);
            }
          }
        }
      }
    }
    &.navbar-dark {
      .navbar-menu-wrapper {
        border-left-color: darken($border-color, 50%);
      }
    }
    &.navbar-danger {
      .navbar-menu-wrapper {
        .nav-item {
          .nav-link {
            &.count-indicator {
              .count {
                background: $primary;
              }
            }
          }
        }
      }
    }
  }
}
@media (max-width:991px) {
  .navbar {
    -webkit-box-orient: horizontal;
    -webkit-box-direction: normal;
        -ms-flex-direction: row;
            flex-direction: row;
    .navbar-brand-wrapper {
      width: 55px;
      .navbar-brand {
        &.brand-logo {
          display: none;
        }
        &.brand-logo-mini {
          display: inline-block;
        }
      }
    }
  }

  .navbar-collapse {
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    margin-top: 0.5rem;
  }
}

@media (max-width:480px) {
  .navbar {
    .navbar-brand-wrapper {
      width: 55px;
      .brand-logo-mini{
        padding-top: 0px;
      }
    }
  }
}

.navbar-breadcrumb {
  background: #00c8bf;
  margin-top: $navbar-height;
  .navbar-links-wrapper {
    transition: width $action-transition-duration $action-transition-timing-function, background $action-transition-duration $action-transition-timing-function;
    -webkit-transition: width $action-transition-duration $action-transition-timing-function, background $action-transition-duration $action-transition-timing-function;
    -moz-transition: width $action-transition-duration $action-transition-timing-function, background $action-transition-duration $action-transition-timing-function;
    -ms-transition: width $action-transition-duration $action-transition-timing-function, background $action-transition-duration $action-transition-timing-function;
    width: calc(#{$sidebar-width-lg} + #{$sidebar-margin-left});
    height: $navbar-breadcrumb-height;
    @media(max-width: 991px) {
      width: 0;
    }
    .nav-link {
      display: none;
      @media(min-width: 991px) {
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        -webkit-box-flex: 1;
            -ms-flex-positive: 1;
                flex-grow: 1;
        -webkit-box-align: center;
            -ms-flex-align: center;
                align-items: center;
        -webkit-box-pack: center;
            -ms-flex-pack: center;
                justify-content: center;
        border-right: 1px solid #56d3c9;
      }
      a {
      color: #fff;
      font-size: 1.187rem;
      }
    }
  }
  .navbar-menu-wrapper {
    transition: width $action-transition-duration $action-transition-timing-function;
    -webkit-transition: width $action-transition-duration $action-transition-timing-function;
    -moz-transition: width $action-transition-duration $action-transition-timing-function;
    -ms-transition: width $action-transition-duration $action-transition-timing-function;
    color: $navbar-menu-color;
    padding-left: 1.812rem;
    padding-right: 1.812rem;
    width: calc(100% - #{$sidebar-width-lg} - #{$sidebar-margin-left});
    height: $navbar-breadcrumb-height;
    @media (max-width: 991px) {
      width: 100%;
      padding-left: 15px;
      padding-right: 15px;
    }
    .navbar-nav {
      @include display-flex;
      @include flex-direction(row);
      @include align-items(center);

      .nav-item {
        margin-left: 0.593rem;
        margin-right: 0.593rem;
        color: white;
        &.nav-search {
          margin-left: 2rem;
          .input-group {
            background: #fff;
            border-radius: 2px;
            .form-control,
            .input-group-text {
              background: transparent;
              border: 0;
              color: #001737;
              padding: 0;
              height: auto;
            }
            .form-control {
              margin-left: .5rem;
              height: 2.312rem;
              padding: 0 .4rem;
              width: 13.375rem;
              @include placeholder {
                color: #a5abcc;
              }
            }
            .input-group-prepend {
              background: $danger;
              cursor: pointer;
              border-radius: 0 2px 2px 0;
              width: 2.75rem;
              -webkit-box-pack: center;
                  -ms-flex-pack: center;
                      justify-content: center;
              .input-group-text {
                color: $white;
                font-size: 1.25rem;
              }
            }
          }
        }
      }
      &.navbar-nav-right {
        margin-left: auto;
      }
    }
  }
}
